		XrceTransport *self = (XrceTransport *)p_args;
		g_diag.topic_callbacks++;
		for (const KeyValue<int, Endpoint> &kv : self->subs) {
			if (kv.value.entity.id == p_object.id && kv.value.entity.type == p_object.type) {
